mapper.select:
SELECT
    p.*,
    s.`name` as sceneName,
    t.`name` as targetName
FROM
    gift_product p
LEFT JOIN gift_scene s ON p.scene_id = s.id
LEFT JOIN gift_target t ON p.target_id = t.id


        and p.`name` like concat('%', #{param.name}, '%')


        and p.status = #{param.status}


        and p.good_pick = #{param.goodPick}


        and p.special_offer = #{param.specialOffer}


        and p.type_id = #{param.typeId}


        and p.scene_id = #{param.sceneId}


        and p.target_id = #{param.targetId}


        and p.price >= #{param.startBudget}


        and #{param.endBudget} >= p.price


order by p.create_time desc
